[{"path":"scripts/ai-content.ts","content":"import { allPrompts } from "../src/prompts";
import { learningPrompts } from "../src/content/learning";
import { companionArticles } from "../src/content/companion-guides";
import { expandedArticles } from "../src/content/expanded-reading";
import { compatibleScenes, composeScene } from "../src/scenes";
import { promptText, learningPromptText } from "../src/prompt-text";
export function buildDocuments(): Record<string, string> {
  const files: Record<string, string> = {};
  for (const language of ["zh", "en"] as const) {
    const index = [
      `# TalkSprout — ${language === "en" ? "English practice library" : "英语学习目录"}`,
      "Prompt bodies are English learning instructions. Read the selected document before starting; preserve its coaching loop.",
    ];
    const catalogs: Record<string, string[]> = {};
    const add = (path: string, title: string, body: string) => {
      files[path] = `# ${title}\n\n${body}\n`;
      const directory = path.slice(0, path.lastIndexOf("/"));
      (catalogs[directory] ??= []).push(
        `- [${title}](${path.slice(directory.length + 1)})`,
      );
    };
    for (const p of allPrompts) {
      add(
        `${language}/prompts/${p.id}.md`,
        language === "en" ? p.english : p.title,
        `${language === "en" ? p.guideEn : p.guide}\n\n## Full prompt\n\n${promptText(p, "full", "current", language)}\n\n## Spoken opening\n\n${promptText(p, "spoken", "current", language)}${p.kind === "review" ? `\n\n## Another transcript\n\n${promptText(p, "full", "transcript", language)}` : ""}`,
      );
      for (const scene of compatibleScenes(p)) {
        for (const pace of (p.id === "roleplay-coach" &&
        scene.category === "interview"
          ? ["coached", "mock"]
          : ["coached"]) as ("coached" | "mock")[]) {
          const composed = composeScene(p, {
            sceneId: scene.id,
            background: "",
            pace,
          });
          add(
            `${language}/scenarios/${p.id}/${scene.id}${pace === "mock" ? "-mock" : ""}.md`,
            `${scene.title[language]} — ${p.english} (${pace})`,
            `${promptText(composed, "full", "current", language)}\n\n## Spoken opening\n\n${promptText(composed, "spoken", "current", language)}`,
          );
        }
      }
    }
    for (const p of learningPrompts)
      add(
        `${language}/prompts/${p.id}.md`,
        p.title[language],
        `${p.preparation[language]}\n\n${p.guide[language]}\n\n${learningPromptText(p, language)}`,
      );
    for (const a of [...companionArticles, ...expandedArticles])
      add(
        `${language}/guides/${a.id}.md`,
        a.title[language],
        `${a.summary[language]}\n\n${a.sections.map((s) => `## ${s.title[language]}\n\n${(s.paragraphs ?? []).map((t) => t[language]).join("\n\n")}\n\n${(s.steps ?? []).map((t, i) => `${i + 1}. ${t[language]}`).join("\n")}\n\n${s.example ?? ""}\n\n${s.prompt?.body ?? ""}`).join("\n\n")}`,
      );
    for (const [directory, links] of Object.entries(catalogs)) {
      files[`${directory}/index.md`] =
        `# TalkSprout — ${directory.split("/").slice(1).join(" / ")}\n\n${links.join("\n")}\n`;
    }
    files[`${language}/scenarios/index.md`] =
      `# ${language === "en" ? "Choose a conversation coach, then a scenario" : "先选择教练，再选择场景"}\n\n` +
      allPrompts
        .filter((p) => compatibleScenes(p).length)
        .map(
          (p) =>
            `- [${language === "en" ? p.english : p.title}](${p.id}/index.md)`,
        )
        .join("\n") +
      "\n";
    index.push(
      `- [${language === "en" ? "Coaches, reviews and listening/reading/writing" : "教练、复习与听读写练习"}](prompts/index.md)`,
      `- [${language === "en" ? "Compatible scenarios and interview pacing" : "兼容场景与面试节奏"}](scenarios/index.md)`,
      `- [${language === "en" ? "Learning guides and AI configurations" : "学习指南与 AI 配置"}](guides/index.md)`,
    );
    files[`${language}/index.md`] = index.join("\n\n") + "\n";
  }
  return files;
}
"},{"path":"scripts/sync-ai.ts","content":"import { readFile, writeFile, mkdir, readdir } from "node:fs/promises";
import { dirname } from "node:path";
import { createHash } from "node:crypto";
import { buildDocuments } from "./ai-content";
const config = JSON.parse(await readFile("distribution/config.json", "utf8"));
const guidance = JSON.parse(
  await readFile("distribution/guidance.json", "utf8"),
);
const files = buildDocuments();
const hash = (s: string | Buffer) =>
  createHash("sha256").update(s).digest("hex");
const releaseInputs = [
  "distribution/config.json",
  "distribution/guidance.json",
  "scripts/sync-ai.ts",
  "scripts/ai-content.ts",
  "scripts/package-skill.py",
  "scripts/package-check.py",
  "mcp/src/server.ts",
  "mcp/src/index.ts",
  "mcp/cloudflare.config.ts",
  "mcp/pnpm-lock.yaml",
  "src/AISetup.tsx",
  "scripts/release_policy.py",
  "scripts/publish-ai.py",
  "scripts/verify-mcp.ts",
  "scripts/mcp-verification.ts",
  ".github/workflows/pages.yml",
];
const releaseInputsVersion = hash(
  JSON.stringify(
    await Promise.all(
      releaseInputs.map(async (path) => [path, await readFile(path, "utf8")]),
    ),
  ),
);
const identity = {
  releaseInputsVersion,
  name: config.name,
  version: config.version,
  contentVersion: hash(JSON.stringify(files)),
  guidanceVersion: hash(JSON.stringify(guidance)),
  iconSha256: hash(await readFile(config.icon)),
};
const fingerprint = hash(JSON.stringify(identity));
const json = (v: unknown) => JSON.stringify(v, null, 2) + "\n";
const skill = `---
name: talksprout
description: Practice English with TalkSprout conversation coaches, role-play and interview scenarios, conversation reviews, and source-grounded listening, reading and writing tasks. Use when the learner requests TalkSprout or these English practice workflows.
---
# TalkSprout

## Retrieve only the selected task
If TalkSprout MCP tools are already connected, call get_guide and keep its returned content identity and sourceRevision for this task, then use read_document with an exact returned path. Installing a release-pinned Skill does not pin the connected MCP deployment: choosing MCP explicitly chooses the server's identity. Do not silently combine that route with release-pinned web documents. If the learner explicitly requires the package revision, compare the server sourceRevision with references/release.md and use the pinned web route when they differ; explain if neither matching route is accessible. Otherwise read ${config.contentBase}en/index.md or ${config.contentBase}zh/index.md with the host's public URL reader. Choose the index for the learner's language. Follow its relative links using the same content base and revision. Read only the selected prompt, scenario or guide, and retain that document throughout the task. Do not retrieve the whole library.

If raw GitHub cannot be read, try the same path and revision once through https://github.com/OctopusGarage/talksprout/blob/main/content/. If neither route works, explain the limitation and ask for pasted material. Do not install runtimes or run shell commands to read learning content. Installing this skill does not connect MCP automatically.

## Choose the workflow
Offer actual index choices when the request is broad. For conversations select a coach and optional compatible scenario; mock interview documents explicitly defer feedback. Reviews use the current accessible chat or the speaker-labeled transcript template. Listening, reading and writing documents specify required source material. Guides explain methods and provide reusable configurations. Follow explicit help, review and stop requests.

## Learning boundaries
${guidance.instructions}
`;
const manifest = {
  name: config.name,
  version: config.version,
  description: config.description,
  author: { name: config.publisher, url: "https://github.com/OctopusGarage" },
  homepage: config.repository,
  repository: config.repository,
  license: "MIT",
  keywords: ["english", "learning", "coaching", "talksprout"],
};
const outputs: Record<string, string | Buffer> = {
  ...Object.fromEntries(
    Object.entries(files).map(([path, body]) => ["content/" + path, body]),
  ),
  "distribution/identity.json": json({ ...identity, fingerprint }),
  "mcp/package.json": json({
    ...JSON.parse(await readFile("mcp/package.json", "utf8")),
    version: config.version,
  }),
  "mcp/generated/library.json": json({
    endpoint: config.mcpEndpoint,
    ...identity,
    fingerprint,
    sourceRevision:
      process.env.AI_SOURCE_REVISION || process.env.GITHUB_SHA || "local",
    iconBase64: (await readFile(config.icon)).toString("base64"),
    guidance: guidance.instructions,
    files,
  }),
  "skills/talksprout/SKILL.md": skill,
  "skills/talksprout/LICENSE": await readFile("LICENSE"),
  "skills/talksprout/assets/icon.png": await readFile(config.icon),
  "skills/talksprout/agents/openai.yaml": `interface:\n  display_name: "TalkSprout"\n  short_description: "English practice and review"\n  default_prompt: "Use $talksprout to help me practice English."\n  icon_small: "./assets/icon.png"\n  icon_large: "./assets/icon.png"\n`,
  "distribution/plugins/talksprout/claude-plugin.json": json(manifest),
  "distribution/plugins/talksprout/plugin.json": json({
    $schema: "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
    ...manifest,
    extensions: {
      "com.openai": {
        interface: {
          displayName: config.displayName,
          shortDescription: "English practice and review",
          longDescription: config.description,
          developerName: config.publisher,
          category: "Productivity",
          capabilities: ["Read"],
          websiteURL: config.repository,
          defaultPrompt: [
            "Use TalkSprout to practice a workplace conversation.",
          ],
          composerIcon: "./assets/icon.png",
          logo: "./assets/icon.png",
        },
      },
    },
  }),
  "distribution/plugins/talksprout/README.md":
    "# TalkSprout plugin\n\nInstall through a supported host plugin flow and enable the TalkSprout skill. Requires public URL reading or an already connected TalkSprout MCP. This package does not connect MCP or access private app data. Host availability depends on account and workspace controls.\n",
};
let stale = false;
for (const [path, data] of Object.entries(outputs)) {
  if (process.argv.includes("--check")) {
    const current = await readFile(path).catch(() => Buffer.alloc(0));
    if (!current.equals(Buffer.from(data))) {
      console.error("Stale: " + path);
      stale = true;
    }
  } else {
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, data);
  }
}
async function checkExtras(dir: string) {
  for (const entry of await readdir(dir, { withFileTypes: true }).catch(
    () => [],
  )) {
    const path = dir + "/" + entry.name;
    if (entry.isDirectory()) await checkExtras(path);
    else if (!(path in outputs)) {
      console.error("Unexpected generated file: " + path);
      stale = true;
    }
  }
}
await checkExtras("content");
if (stale) process.exitCode = 1;
console.log(`${Object.keys(files).length} documents; identity ${fingerprint}`);
"},{"path":"scripts/package-skill.py","content":"#!/usr/bin/env python3
"""Create deterministic, content-free skill and host-specific plugin archives."""
from pathlib import Path
from zipfile import ZipFile, ZipInfo, ZIP_DEFLATED
import argparse
import json
import os
import re

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "skills" / "talksprout"
PACKAGE_NAMES = json.loads((ROOT / "distribution" / "config.json").read_text())["packages"]
TARGET = ROOT / "public" / "downloads" / PACKAGE_NAMES["skill"]
PLUGIN_TARGET = ROOT / "public" / "downloads" / PACKAGE_NAMES["plugin"]
CLAUDE_TARGET = ROOT / "public" / "downloads" / PACKAGE_NAMES["claudePlugin"]

def package(target=TARGET, plugin=False, claude=False):
    target = Path(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    config = json.loads((ROOT / "distribution" / "config.json").read_text())
    identity = json.loads((ROOT / "distribution" / "identity.json").read_text())
    revision = os.environ.get("AI_SOURCE_REVISION") or os.environ.get("GITHUB_SHA", "local")
    if revision != "local" and not re.fullmatch(r"[a-f0-9]{40}", revision):
        raise ValueError("Invalid source revision")
    files = []
    if plugin:
        files.extend([
            (".claude-plugin/plugin.json" if claude else "plugin.json", ROOT / "distribution" / "plugins" / "talksprout" / ("claude-plugin.json" if claude else "plugin.json")),
            ("LICENSE", SOURCE / "LICENSE"),
            ("README.md", ROOT / "distribution" / "plugins" / "talksprout" / "README.md"),
            ("assets/icon.png", ROOT / config["icon"]),
        ])
    for path in sorted(SOURCE.rglob("*")):
        if "__pycache__" in path.parts or path.suffix == ".pyc":
            continue
        if path.is_symlink():
            raise ValueError("Skill package must not contain symlinks")
        if path.is_file():
            relative = path.relative_to(SOURCE).as_posix()
            if relative not in {"SKILL.md", "LICENSE", "agents/openai.yaml", "assets/icon.png"}:
                raise ValueError(f"Unexpected consumer package file: {relative}")
            prefix = "skills/talksprout/" if plugin else "talksprout/"
            files.append((prefix + path.relative_to(SOURCE).as_posix(), path))
    with ZipFile(target, "w", compression=ZIP_DEFLATED, compresslevel=9) as archive:
        for name, path in sorted(files):
            if path.is_symlink():
                raise ValueError("Skill package must not contain symlinks")
            if not path.is_file():
                raise ValueError(f"Missing package asset: {path}")
            entry = ZipInfo(name, (1980, 1, 1, 0, 0, 0))
            entry.compress_type = ZIP_DEFLATED
            entry.external_attr = 0o100644 << 16
            data = path.read_bytes()
            if path.name == "SKILL.md" and revision != "local":
                data = data.replace(b"/talksprout/main/content/", f"/talksprout/{revision}/content/".encode())
                data = data.replace(b"/talksprout/main/", f"/talksprout/{revision}/".encode())
                data = data.replace(b"/talksprout/blob/main/", f"/talksprout/blob/{revision}/".encode())
            archive.writestr(entry, data)
        release_path = ("skills/talksprout/" if plugin else "talksprout/") + "references/release.md"
        entry = ZipInfo(release_path, (1980, 1, 1, 0, 0, 0))
        entry.compress_type = ZIP_DEFLATED
        entry.external_attr = 0o100644 << 16
        release = f"# TalkSprout release\n\nVersion: {config['version']}\n\nContent version: {identity['contentVersion']}\n\nGuidance version: {identity['guidanceVersion']}\n\nSource revision: {revision}\n\nCI release archives pin learning content links to this source revision. Repository installations follow the current main branch. Keep retrieved text during an active learning conversation.\n"
        archive.writestr(entry, release.encode())
    print(f"Packaged {target.name} ({target.stat().st_size} bytes); learning documents remain on the public feed.")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path)
    parser.add_argument("--format", choices=["skill", "plugin", "claude", "all"])
    args = parser.parse_args()
    kind = args.format or ("skill" if args.output else "all")
    if kind == "all" and args.output:
        parser.error("--output requires --format skill or plugin")
    if kind == "all":
        for retired in {"talksprout-plugin.zip", "talksprout-chatgpt-plugin.zip"} - set(PACKAGE_NAMES.values()):
            (ROOT / "public" / "downloads" / retired).unlink(missing_ok=True)
    if kind in ("skill", "all"):
        package(args.output or TARGET)
    if kind in ("plugin", "all"):
        package(args.output or PLUGIN_TARGET, plugin=True)
    if kind in ("claude", "all"):
        package(args.output or CLAUDE_TARGET, plugin=True, claude=True)
"},{"path":"scripts/package-check.py","content":"from pathlib import Path
from zipfile import ZipFile
import hashlib, json
root=Path(__file__).resolve().parents[1]
config=json.loads((root/'distribution/config.json').read_text())
checks=[]
for kind,name in config['packages'].items():
 path=root/'public/downloads'/name
 with ZipFile(path) as z:
  names=z.namelist()
  prefix='talksprout/' if kind=='skill' else 'skills/talksprout/'
  assert prefix+'SKILL.md' in names
  assert prefix+'references/release.md' in names
  assert all(not n.startswith('/') and '..' not in n.split('/') for n in names)
  assert len(names)==len(set(names))
  if kind!='skill':
   manifest='.claude-plugin/plugin.json' if kind=='claudePlugin' else 'plugin.json'
   assert json.loads(z.read(manifest))['version']==config['version']
  assert not any(n.endswith(('.py','.ts','.env')) for n in names)
 checks.append(hashlib.sha256(path.read_bytes()).hexdigest()+'  '+name)
identity=json.loads((root/'distribution/identity.json').read_text())
import os
manifest=dict(schemaVersion=1,**identity,sourceRevision=os.environ.get('AI_SOURCE_REVISION') or os.environ.get('GITHUB_SHA','local'),mcpEndpoint=config['mcpEndpoint'],assets={name:dict(sha256=hashlib.sha256((root/'public/downloads'/name).read_bytes()).hexdigest(),bytes=(root/'public/downloads'/name).stat().st_size) for name in config['packages'].values()})
manifest_path=root/'public/downloads/release-manifest.json'
manifest_path.write_text(json.dumps(manifest,indent=2)+'\n')
checks.append(hashlib.sha256(manifest_path.read_bytes()).hexdigest()+'  release-manifest.json')
(root/'public/downloads/SHA256SUMS').write_text('\n'.join(checks)+'\n')
print('Validated all three archives and wrote SHA256SUMS')
