import { readFileSync } from "node:fs";
import test from "node:test";
import assert from "node:assert/strict";
import { createMcpHandler } from "agents/mcp/server";
import { createServer } from "../src/server";

const handler = createMcpHandler(createServer, {
  responseMode: "json",
  legacy: "stateless",
  allowedOriginHostnames: [
    "chatgpt.com",
    "claude.ai",
    "gemini.google.com",
    "www.doubao.com",
    "doubao.com",
  ],
});
async function rpc(
  id: number,
  method: string,
  params: Record<string, unknown>,
  version = "2025-03-26",
) {
  const modern = version === "2026-07-28";
  const body = {
    jsonrpc: "2.0",
    id,
    method,
    params: modern
      ? {
          ...params,
          _meta: {
            "io.modelcontextprotocol/protocolVersion": version,
            "io.modelcontextprotocol/clientInfo": {
              name: "talksprout-test",
              version: "1.0.0",
            },
            "io.modelcontextprotocol/clientCapabilities": {},
          },
        }
      : params,
  };
  const headers: Record<string, string> = {
    Host: "localhost",
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    "MCP-Protocol-Version": version,
  };
  if (modern) {
    headers["Mcp-Method"] = method;
    if (method === "tools/call") headers["Mcp-Name"] = String(params.name);
  }
  const response = await handler.fetch(
    new Request("http://localhost/mcp", {
      method: "POST",
      headers,
      body: JSON.stringify(body),
    }),
  );
  assert.equal(response.status, 200, await response.clone().text());
  const text = await response.text();
  const payload = response.headers
    .get("content-type")
    ?.includes("text/event-stream")
    ? text
        .split("\n")
        .filter((line) => line.startsWith("data:"))
        .map((line) => JSON.parse(line.slice(5)))
        .find((message) => message.id === id)
    : JSON.parse(text);
  const result = payload as {
    id: number;
    result: {
      tools?: { name: string }[];
      content?: { text: string }[];
      isError?: boolean;
      structuredContent?: Record<string, unknown>;
    };
    error?: unknown;
  };
  assert.equal(result.id, id);
  assert.ok(!result.error, JSON.stringify(result.error));
  return result.result;
}
test("wire protocol lists tools, retrieves full documents and rejects traversal", async () => {
  const init = await rpc(1, "initialize", {
    protocolVersion: "2025-03-26",
    capabilities: {},
    clientInfo: { name: "test", version: "1.0" },
  });
  assert.ok(init);
  const listed = await rpc(2, "tools/list", {});
  assert.equal(listed.tools?.length, 3);
  const read = await rpc(3, "tools/call", {
    name: "read_document",
    arguments: { path: "en/prompts/roleplay-coach.md" },
  });
  assert.equal(
    read.content?.[0].text,
    readFileSync(
      new URL("../../content/en/prompts/roleplay-coach.md", import.meta.url),
      "utf8",
    ),
  );
  const bad = await rpc(4, "tools/call", {
    name: "read_document",
    arguments: { path: "../secret" },
  });
  assert.equal(bad.isError, true);
});

test("modern stateless protocol reads guide without initialization", async () => {
  const guide = await rpc(
    10,
    "tools/call",
    { name: "get_guide", arguments: { language: "zh" } },
    "2026-07-28",
  );
  assert.match(guide.content?.[0].text ?? "", /zh\/index.md/);
});
"},{"path":"scripts/verify-mcp.ts","content":"import { assertCompleteDocument } from "./mcp-verification";
import { readFile } from "node:fs/promises";
const endpoint = process.argv[2];
if (!endpoint || !endpoint.startsWith("https://") || !endpoint.endsWith("/mcp"))
  throw Error("Pass the deployed HTTPS /mcp endpoint");
const identity = JSON.parse(
  await readFile(process.argv[3] || "distribution/identity.json", "utf8"),
);
const response = await fetch(new URL("/health", endpoint));
if (!response.ok) throw Error("Health failed: " + response.status);
const health = await response.json();
for (const key of [
  "name",
  "version",
  "contentVersion",
  "guidanceVersion",
  "fingerprint",
  "iconSha256",
])
  if (health[key] !== identity[key]) throw Error("Identity mismatch: " + key);
const revision =
  identity.sourceRevision ||
  process.env.AI_SOURCE_REVISION ||
  process.env.GITHUB_SHA;
if (revision && health.sourceRevision !== revision)
  throw Error("Deployed source revision mismatch");
for (const [id, method, params] of [
  {
    id: 1,
    method: "initialize",
    params: {
      protocolVersion: "2025-03-26",
      capabilities: {},
      clientInfo: { name: "talksprout-smoke", version: "1.0" },
    },
  },
  { id: 2, method: "tools/list", params: {} },
  {
    id: 3,
    method: "tools/call",
    params: {
      name: "read_document",
      arguments: { path: "en/prompts/roleplay-coach.md" },
    },
  },
].map((p) => [p.id, p.method, p.params] as const)) {
  const res = await fetch(endpoint, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
      "MCP-Protocol-Version": "2025-03-26",
    },
    body: JSON.stringify({ jsonrpc: "2.0", id, method, params }),
  });
  const text = await res.text();
  if (!res.ok) throw Error(`Protocol ${method}: ${res.status}`);
  const result = res.headers.get("content-type")?.includes("text/event-stream")
    ? text
        .split("\n")
        .filter((l) => l.startsWith("data:"))
        .map((l) => JSON.parse(l.slice(5)))
        .find((p) => p.id === id)
    : JSON.parse(text);
  if (!result?.result || result.error || result.result.isError)
    throw Error("Protocol failure: " + method);
  if (
    method === "tools/list" &&
    !["get_guide", "read_document", "search_documents"].every((name) =>
      result.result.tools.some((t: { name: string }) => t.name === name),
    )
  )
    throw Error("Missing tools");
  if (method === "tools/call")
    assertCompleteDocument(
      result.result,
      await readFile("content/en/prompts/roleplay-coach.md", "utf8"),
    );
}
const iconResponse = await fetch(
  new URL(`/icons/${identity.iconSha256}.png`, endpoint),
);
if (!iconResponse.ok) throw Error("Icon unavailable");
const { createHash } = await import("node:crypto");
if (
  createHash("sha256")
    .update(new Uint8Array(await iconResponse.arrayBuffer()))
    .digest("hex") !== identity.iconSha256
)
  throw Error("Deployed icon mismatch");
console.log("Deployed health identity and MCP protocol verified");
"},{"path":"scripts/mcp-verification.ts","content":"/** Verify the entire document instead of accepting an answer-bearing marker. */
export function assertCompleteDocument(value: unknown, expected: string): void {
  const response = value as {
    content?: { type?: string; text?: string }[];
  } | null;
  if (
    !expected ||
    !Array.isArray(response?.content) ||
    response.content.length !== 1 ||
    response.content[0]?.type !== "text" ||
    response.content[0]?.text !== expected
  )
    throw Error("MCP returned an incomplete or mismatched document");
}
"},{"path":"tests/mcp-verification.test.ts","content":"import test from "node:test";
import assert from "node:assert/strict";
import { assertCompleteDocument } from "../scripts/mcp-verification";
test("remote verification requires the exact complete document, not its heading", () => {
  const expected = "# Coach\n\n## Full prompt\nComplete instructions.\n";
  assert.doesNotThrow(() =>
    assertCompleteDocument(
      { content: [{ type: "text", text: expected }] },
      expected,
    ),
  );
  for (const text of [
    "## Full prompt",
    expected.slice(0, -2),
    expected + "extra",
    "wrong locale",
  ])
    assert.throws(() =>
      assertCompleteDocument({ content: [{ type: "text", text }] }, expected),
    );
  for (const response of [
    null,
    {},
    { content: [] },
    { content: [{ type: "image", text: expected }] },
  ])
    assert.throws(() => assertCompleteDocument(response, expected));
});
"}]

