  margin: 0 0 20px;
}
.scene-trigger,
.scene-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 64px;
  padding: 12px 14px;
  text-align: left;
}
.scene-trigger {
  border-radius: 14px;
  background: var(--canvas);
